  "high": "tinggi", "nominal": "nominal", "low": "rendah", "settlement": "permukiman", "road": "jalan", "river": "sungai", "lake or pond": "danau atau kolam", "fire station": "pos pemadam",
  "{n} FIRMS hotspot(s), max FRP {frp} MW, confidence: {conf}": "{n} titik panas FIRMS, FRP maksimum {frp} MW, keyakinan: {conf}",
